CREATE TABLE IF NOT EXISTS magic_components (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, variant TEXT, props JSONB DEFAULT '{}', preview_route TEXT, score INTEGER, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
CREATE TABLE IF NOT EXISTS component_variants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, component_id UUID NOT NULL, name TEXT NOT NULL, props_overrides JSONB DEFAULT '{}', is_default BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
CREATE TABLE IF NOT EXISTS component_usage_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, component_name TEXT NOT NULL, route TEXT NOT NULL, used_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
